import { Component, OnInit } from '@angular/core';
import { Flights, FlightsService } from 'src/app/services/flights.service';
import { UserHttpService } from 'src/app/user-http.service';

@Component({
  selector: 'app-flights',
  templateUrl: './flights.component.html',
  styleUrls: ['./flights.component.css']
})
export class FlightsComponent implements OnInit {
  flights: Flights[] = [];

  // Form per aggiungere/modificare volo
  newFlight: Partial<Flights> = {
    _flightcode: '',
    route: '',
    aircraft: '',
    duration: 0,
    dataOra: ''
  };

  editedFlight: any = {
    aircraft: '', 
    duration: 0, 
    dataOra: ''
  };

  editingFlightCode: string | null = null;

  constructor(
    private flightService: FlightsService,
    private us: UserHttpService
  ) {}

  ngOnInit() {
    this.loadFlights();
  }

  loadFlights() {
    this.flightService.getFlights().subscribe({
      next: (data) => {
        this.flights = data;
      },
      error: (err) => {
        console.error('Errore caricamento voli:', err);
      }
    });
  }

  addFlight() {
    if (!this.newFlight._flightcode || !this.newFlight.route || !this.newFlight.aircraft || !this.newFlight.dataOra) {
      alert('Compila tutti i campi richiesti.');
      return;
    }

    const flightData: Flights = {
      _flightcode: this.newFlight._flightcode,
      route: this.newFlight.route,
      aircraft: this.newFlight.aircraft,
      duration: this.newFlight.duration ?? 0,
      dataOra: this.newFlight.dataOra
    };

    this.flightService.addFlights(flightData).subscribe({
      next: () => {
        alert('Volo aggiunto con successo.');
        this.newFlight = {
          _flightcode: '',
          route: '',
          aircraft: '',
          duration: 0,
          dataOra: ''
        };
        this.loadFlights();
      },
      error: (err) => {
        console.error('Errore durante l\'aggiunta del volo:', err);
        alert('Errore durante l\'aggiunta del volo.');
      }
    });
  }

  deleteFlight(flight: Flights) {
    this.flightService.deleteFlights(flight._flightcode).subscribe({
      next: () => {
        alert('Volo eliminato con successo.');
        this.loadFlights();
      },
      error: (err) => {
        console.error('Errore durante la cancellazione del volo:', err);
        alert('Errore durante la cancellazione del volo.');
      }
    });
  }

  startEditing(flight: Flights) {
    this.editingFlightCode = flight._flightcode;
    this.editedFlight = { ...flight }; // crea una copia modificabile
  }

  cancelEditing() {
    this.editingFlightCode = null;
    this.editedFlight = {aircraft: '', duration: 0, dataOra: ''};
  }

  saveFlightChanges() {
    if (!this.editingFlightCode) return;

    this.flightService.updateFlights(this.editingFlightCode, this.editedFlight).subscribe({
      next: () => {
        alert('Volo modificato con successo');
        this.editingFlightCode = null;
        this.loadFlights();
      },
      error: (err) => {
        console.error("Errore durante la modifica del volo:", err);
        alert("Errore modifica Volo");
      } 
    });
  }
}
